// Code 39 SVG for printable shop labels; supports standard ASCII-39 characters.
const proCode39Patterns={
'0':'nnnwwnwnn','1':'wnnwnnnnw','2':'nnwwnnnnw','3':'wnwwnnnnn','4':'nnnwwnnnw','5':'wnnwwnnnn','6':'nnwwwnnnn','7':'nnnwnnwnw','8':'wnnwnnwnn','9':'nnwwnnwnn',
'A':'wnnnnwnnw','B':'nnwnnwnnw','C':'wnwnnwnnn','D':'nnnnwwnnw','E':'wnnnwwnnn','F':'nnwnwwnnn','G':'nnnnnwwnw','H':'wnnnnwwnn','I':'nnwnnwwnn','J':'nnnnwwwnn',
'K':'wnnnnnnww','L':'nnwnnnnww','M':'wnwnnnnwn','N':'nnnnwnnww','O':'wnnnwnnwn','P':'nnwnwnnwn','Q':'nnnnnnwww','R':'wnnnnnwwn','S':'nnwnnnwwn','T':'nnnnwnwwn',
'U':'wwnnnnnnw','V':'nwwnnnnnw','W':'wwwnnnnnn','X':'nwnnwnnnw','Y':'wwnnwnnnn','Z':'nwwnwnnnn',
'-':'nwnnnnwnw','.':'wwnnnnwnn',' ':'nwwnnnwnn','$':'nwnwnwnnn','/':'nwnwnnnwn','+':'nwnnnwnwn','%':'nnnwnwnwn','*':'nwnnwnwnn'
};
function proCode39SVG(raw){
 const value=String(raw||'').trim().toUpperCase();
 if(!value||value.length>38||![...value].every(ch=>ch!=='*'&&proCode39Patterns[ch]))throw Error('This barcode cannot be printed in Code 39. Use letters A–Z, numbers, spaces and - . $ / + %.');
 // 1 quiet zone each side (at least ten narrow units), narrow:wide = 1:3.
 let x=12;const rects=[];
 for(const ch of '*'+value+'*'){
  const pattern=proCode39Patterns[ch];
  for(let j=0;j<pattern.length;j++){
   const width=pattern[j]==='w'?3:1;
   if(j%2===0)rects.push(`<rect x="${x}" y="0" width="${width}" height="72" fill="#000"/>`);
   x+=width;
  }
  x+=1;
 }
 const width=x+12;
 return `<svg class="pro-barcode-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} 72" role="img" aria-label="Barcode ${esc(value)}">${rects.join('')}</svg>`;
}
function proProductLabel(id){
 const p=state.products.find(x=>x.id===id);if(!p)return;
 const code=String(p.barcode||p.sku).trim();
 const svg=proCode39SVG(code);
 proModal('Print Product Label',`<div class="receipt-area"><div class="pro-label-paper"><b>FLEXICO WATCHES</b><div class="pro-label-product">${esc(p.name)} · ${esc(p.variant||'')}</div>${svg}<strong class="pro-label-code">${esc(code)}</strong><div class="pro-label-price">${pkr(itemPrice(p))}</div></div></div><p class="page-sub">Print preview par apne label-paper size aur scale ko adjust karein. Scanner compatibility ko physical scanner se test karein.</p><button class="btn btn-primary" data-action="print-receipt">Print Barcode Label</button>`);
}
function proProductImport(){proModal('Import Product CSV',`<div class="grid-form"><div class="pro-info-note">CSV columns: sku, name, barcode, brand, category, variant, cost, price, threshold. Existing SKUs are safely skipped. Max 500 rows per batch.</div><input class="input" type="file" id="pro-csv-input" accept=".csv,text/csv"><button class="btn btn-primary" data-pro="csv-import">Import CSV</button><button class="btn btn-outline" data-pro="csv-template">Download Example CSV</button></div>`);}
function proProductImage(id){proModal('Upload Product Image',`<div class="grid-form"><p class="page-sub">JPG/PNG/WEBP. Image is resized to fit 480 px before upload.</p><input class="input" type="file" id="pro-image-input" accept="image/jpeg,image/png,image/webp"><button class="btn btn-primary" data-pro="image-save" data-id="${id}">Save Image</button></div>`);}
async function resizePhoto(file){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{URL.revokeObjectURL(url);const c=document.createElement('canvas');const scale=Math.min(1,480/Math.max(img.width,img.height));c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.72));};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Could not read image.'));};img.src=url;});}
async function proCoupon(){const code=document.getElementById('coupon-code')?.value.trim().toUpperCase();if(!code){state.couponCode='';state.couponAmount=0;render();return;}
 const subtotal=state.cart.reduce((n,i)=>{const p=state.products.find(x=>x.id===i.id);return n+(p?itemPrice(p)*i.qty:0);},0);const r=await api(`/pro/promo-check?code=${encodeURIComponent(code)}&subtotal=${pkrUnit(subtotal)}`);state.discountValue='0';state.couponCode=r.code;state.couponAmount=r.discount_paisa;cartChanged();render();toast(`${r.code} coupon applied.`);
}
function parseCsv(contents){const lines=[];let record=[],cell='',quoted=false;for(let i=0;i<contents.length;i++){const c=contents[i];if(c==='"'){if(quoted&&contents[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){record.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&contents[i+1]==='\n')i++;record.push(cell);if(record.some(Boolean))lines.push(record);record=[];cell='';}else cell+=c;}if(quoted)throw Error('Unclosed quotes in CSV.');record.push(cell);if(record.some(Boolean))lines.push(record);const columns=lines.shift()?.map(x=>x.trim().toLowerCase().replace(/^\uFEFF/,''))||[];if(!columns.includes('sku')||!columns.includes('name')||!columns.includes('price'))throw Error('CSV needs sku, name and price columns.');return lines.map(row=>Object.fromEntries(columns.map((k,i)=>[k,row[i]||''])));}
function proHoldBill(){if(!state.cart.length)return toast('Add products before holding a bill.','error');proModal('Hold Current Bill',`<form class="grid-form" id="pro-hold-bill">${field('Bill reference / customer name','title','Walk-in customer',true)}<p class="page-sub">Held bills do not reserve stock. Stock will be checked again when you resume and complete a sale.</p><button class="btn btn-primary" type="submit">Save & Hold Bill</button></form>`);}
function proHeldList(){const bills=state.pro.holds||[];proModal('Saved / Held Bills',bills.length?`<div class="grid-form">${bills.map(b=>`<div class="hold-entry"><div><b>${esc(b.title)}</b><small>${b.payload.items.length} SKU(s) · ${formatDate(b.created_at)}</small></div><div class="actions"><button class="btn btn-primary sm" data-pro="bill-load" data-id="${b.id}">Resume</button><button class="btn btn-red sm" data-pro="bill-discard" data-id="${b.id}">Discard</button></div></div>`).join('')}</div>`:'<div class="empty-state">No saved bills yet.</div>');}
function proSupplierPay(id){const po=(state.pro.purchases||[]).find(x=>x.id===id);proModal('Record Supplier Payment',`<form id="pro-supplier-pay" data-id="${id}" class="grid-form"><p class="page-sub">Payable against ${esc(po?.number||'purchase order')}. This records an offline/manual payment and does not transfer money.</p>${field('Paid amount PKR','amount','0',true,'number')}${selectField('Method','method',['Cash','Bank Transfer','Cheque','Wallet'].map(x=>({value:x,label:x})))}${field('Payment reference','reference','')}${field('Notes','notes','')}<button class="btn btn-primary" type="submit">Record Payment</button></form>`);}
function proGiftReceipt(){const s=state.lastSale;if(!s)return;proModal('Gift Receipt · '+s.receipt_no,`<div class="receipt-area"><div class="receipt-paper"><div class="receipt-center"><strong style="font-size:20px">FLEXICO</strong><div>GIFT RECEIPT</div><p>${esc(state.settings.store_name)}</p><small>${esc(state.settings.website||'')}</small></div><hr><div class="rline"><span>Receipt</span><b>${esc(s.receipt_no)}</b></div><div class="rline"><span>Date</span><span>${formatDate(s.created_at)}</span></div><hr>${s.items.map(i=>`<div class="rline"><span>${esc(i.name)}</span><b>${i.qty} item(s)</b></div>`).join('')}<hr><div class="receipt-center"><small>Exchanges subject to store policy. No item prices shown.</small><p>TEST RECEIPT · NOT AN FBR TAX INVOICE</p></div></div></div><button class="btn btn-primary" data-action="print-receipt">Print Gift Receipt</button>`);}
function proWarrantyCard(){const s=state.lastSale;if(!s||!s.warranties?.length)return;proModal('Warranty Card · '+s.receipt_no,`<div class="receipt-area"><div class="receipt-paper"><div class="receipt-center"><strong style="font-size:20px">FLEXICO</strong><div>WARRANTY CARD</div></div><hr><div class="rline"><span>Receipt</span><b>${esc(s.receipt_no)}</b></div><div class="rline"><span>Customer</span><span>${esc(s.customer_name||'Walk-in')}</span></div><hr>${s.warranties.map(w=>`<div><b>Warranty #${w.id}</b><div class="rline"><span>Serial no.</span><span>${esc(w.serial_no||'Not assigned')}</span></div><div class="rline"><span>Starts</span><span>${esc(w.start_date)}</span></div><div class="rline"><span>Expires</span><span>${esc(w.expiry_date)}</span></div></div><hr>`).join('')}<div class="receipt-center"><small>Coverage subject to FLEXICO warranty policy. Retain purchase receipt.</small><div>${esc(state.settings.website||'')}</div></div></div></div><button class="btn btn-primary" data-action="print-receipt">Print Warranty Card</button>`);}
async function proAction(name,el){try{switch(name){
 case 'sync-now':{const result=await api('/sync/now','POST',{});state.pro.sync=result;toast(result.message||'Sync checked.',result.last_error?'error':'success');render();break;}
 case 'customer-edit':{const c=state.customers.find(x=>x.id===Number(el.dataset.id));if(c)proModal('Edit Customer',`<form id="pro-customer-edit" data-id="${c.id}" class="grid-form">${field('Name','name',c.name,true)}${field('Phone','phone',c.phone||'')}${field('Email','email',c.email||'')}${field('City','city',c.city||'')}${field('Address','address',c.address||'')}${field('Notes','notes',c.notes||'')}<button class="btn btn-primary" type="submit">Save Customer</button></form>`);break;}case 'bill-hold':proHoldBill();break;case 'bill-resume':proHeldList();break;
 case 'bill-load':{const held=(state.pro.holds||[]).find(x=>x.id===Number(el.dataset.id));if(!held)throw Error('Held bill no longer available.');if(state.cart.length&&!confirm('Replace current bill with the saved bill?'))break;const b=held.payload;state.cart=b.items;state.saleType=b.saleType;state.customerId=b.customerId;state.discountType=b.discountType;state.discountValue=b.discountValue;state.notes=b.notes;state.couponCode='';state.couponAmount=0;state.payments=[{method:'Cash',amount:'',reference:''}];cartChanged();await api('/pro/holds/'+held.id,'DELETE');state.modal=null;await loadPage('pos');toast('Held bill resumed. Recheck available stock and prices.');break;}
 case 'bill-discard':if(confirm('Discard this saved bill?')){await api('/pro/holds/'+el.dataset.id,'DELETE');state.modal=null;await loadPage('pos');toast('Held bill discarded.');}break;
 case 'gift-receipt':proGiftReceipt();break;case 'warranty-card':proWarrantyCard();break;
 case 'po-payment':proSupplierPay(Number(el.dataset.id));break;
 case 'supplier-new':proSupplierForm();break;case 'supplier-edit':proSupplierForm(Number(el.dataset.id));break;
 case 'po-new':proPurchaseForm();break;case 'po-view':await proPurchaseDetail(Number(el.dataset.id));break;
 case 'po-line-add':document.getElementById('po-lines')?.insertAdjacentHTML('beforeend',poLine());break;
 case 'po-line-remove':if(document.querySelectorAll('.po-line').length>1)el.closest('.po-line')?.remove();break;
 case 'po-receive':{if(!confirm('Receive all items and update inventory?'))break;const id=Number(el.dataset.id),location_id=Number(document.getElementById('receive-location').value);await api(`/pro/purchases/${id}/receive`,'POST',{location_id});state.modal=null;toast('Purchase received, stock updated.');await loadPage('purchases');break;}
 case 'shift-open':proShiftOpen();break;case 'shift-close':proShiftClose(Number(el.dataset.id));break;
 case 'return-start':proReturnStart();break;
 case 'claim-new':proClaimNew();break;case 'claim-edit':proClaimEdit(Number(el.dataset.id));break;case 'serial-edit':proSerialEdit(Number(el.dataset.id));break;
 case 'order-edit':proOrderEdit(Number(el.dataset.id));break;
 case 'promo-new':proPromoNew();break;
 case 'promo-toggle':await api('/pro/promotions/'+el.dataset.id,'PATCH',{active:el.dataset.active==='1'});toast('Promotion changed.');await loadPage('promotions');break;
 case 'count-start':proCountStart();break;case 'count-view':await proCountView(Number(el.dataset.id));break;
 case 'backup-create':{const result=await api('/pro/backups','POST',{});toast('Backup created: '+result.file);await loadPage('audit');break;}
 case 'csv-open':proProductImport();break;
 case 'csv-template':csvDownload('flexico-products-template.csv',[['sku','name','barcode','brand','category','variant','cost','price','threshold'],['FX-SAMPLE-101','Flexico Sample Watch','FLEX101','Flexico','Quartz','Black','5000','10000','5']]);break;
 case 'csv-export':csvDownload(`flexico-products-${today()}.csv`,[['sku','name','barcode','brand','category','variant','cost','price','threshold'],...state.products.map(p=>[p.sku,p.name,p.barcode,p.brand,p.category,p.variant,p.cost,p.price,p.threshold])]);break;
 case 'csv-import':{const f=document.getElementById('pro-csv-input')?.files?.[0];if(!f)throw Error('Select a CSV file first.');if(f.size>400000)throw Error('CSV file is too large.');const products=parseCsv(await f.text());const out=await api('/pro/products/import','POST',{products});state.modal=null;toast(`${out.inserted} imported; ${out.skipped} existing SKUs skipped.`);await loadPage('products');break;}
 case 'product-label':proProductLabel(Number(el.dataset.id));break;case 'image-open':proProductImage(Number(el.dataset.id));break;
 case 'image-save':{const f=document.getElementById('pro-image-input')?.files?.[0];if(!f)throw Error('Select an image first.');if(f.size>10000000)throw Error('Image is too large.');const data=await resizePhoto(f);await api(`/pro/products/${el.dataset.id}/image`,'POST',{image:data});state.modal=null;toast('Product photo updated.');await loadPage('products');break;}
 case 'coupon-apply':await proCoupon();break;
 case 'coupon-clear':state.couponCode='';state.couponAmount=0;render();break;
 default:break;
 }}catch(e){toast(e.message,'error');}}
async function proForm(form){const id=form.id;if(!id.startsWith('pro-'))return false;const b=Object.fromEntries(new FormData(form));try{switch(id){
 case 'pro-hold-bill':{await api('/pro/holds','POST',{title:b.title,items:state.cart,saleType:state.saleType,customerId:state.customerId,discountType:state.discountType,discountValue:state.discountValue,notes:state.notes});state.cart=[];state.customerId='';state.notes='';state.couponCode='';state.couponAmount=0;state.discountValue='0';state.payments=[{method:'Cash',amount:'',reference:''}];cartChanged();break;}
 case 'pro-supplier-pay':await api('/pro/purchases/'+form.dataset.id+'/pay','POST',b);break;
 case 'pro-customer-edit':await api('/pro/customers/'+form.dataset.id,'PATCH',b);break;
 case 'pro-supplier-form':await api('/pro/suppliers'+(form.dataset.id?'/'+form.dataset.id:''),form.dataset.id?'PATCH':'POST',b);break;
 case 'pro-purchase-form':{const lines=[...form.querySelectorAll('.po-line')].map(line=>({product_id:line.querySelector('select').value,qty:line.querySelector('[name=qty]').value,unit_cost:line.querySelector('[name=cost]').value}));await api('/pro/purchases','POST',{supplier_id:b.supplier_id,shipping:b.shipping,notes:b.notes,items:lines});break;}
 case 'pro-shift-open':await api('/pro/shifts','POST',b);break;
 case 'pro-shift-close':{const r=await api('/pro/shifts/'+form.dataset.id+'/close','POST',b);toast(`Shift closed. Variance: ${pkr(r.variance)}.`);break;}
 case 'pro-return-lookup':await proReturnItems(Number(b.sale_id));return true;
 case 'pro-return-form':{const rows=[...form.querySelectorAll('.return-line')].map(line=>({sale_item_id:Number(line.dataset.itemId),qty:Number(line.querySelector('input').value)})).filter(x=>x.qty>0);if(!rows.length)throw Error('Enter the quantity to return.');if(!confirm('Process this refund? This cannot be undone.'))return true;const r=await api('/pro/returns','POST',{sale_id:Number(form.dataset.id),reason:b.reason,refund_method:b.refund_method,override_policy:!!form.querySelector('[name=override_policy]').checked,items:rows});toast('Return processed: '+pkr(r.refund_paisa));break;}
 case 'pro-claim-new':await api('/pro/claims','POST',b);break;
 case 'pro-claim-edit':await api('/pro/claims/'+form.dataset.id,'PATCH',b);break;
 case 'pro-serial-edit':await api('/pro/warranties/'+form.dataset.id,'PATCH',b);break;
 case 'pro-order-edit':b.verified=!!form.querySelector('[name=verified]').checked;await api('/pro/orders/'+form.dataset.id,'PATCH',b);break;
 case 'pro-cod-collect':if(!confirm('Record this real COD collection?'))return true;await api('/pro/orders/'+form.dataset.id+'/collect','POST',b);break;
 case 'pro-promo-new':await api('/pro/promotions','POST',b);break;
 case 'pro-count-start':{const r=await api('/pro/stock-counts','POST',b);state.modal=null;await loadPage('stockcounts');await proCountView(r.id);return true;}
 case 'pro-count-finish':{const items=[...form.querySelectorAll('.count-line')].map(line=>({product_id:Number(line.dataset.pid),counted_qty:Number(line.querySelector('input').value)}));if(!confirm('Finalize this stock count and apply adjustments?'))return true;const r=await api('/pro/stock-counts/'+form.dataset.id+'/finalize','POST',{items});toast(`${r.changed} stock records adjusted.`);break;}
 default:return false;
 }state.modal=null;toast('Saved successfully.');await loadPage(state.page);return true;}catch(err){toast(err.message,'error');return true;}}

